-- Výhradně pro samostatný testovací server na portu 13316.
CREATE DATABASE IF NOT EXISTS rezervace_directory_qa CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE rezervace_directory_qa;
CREATE TABLE companies (id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(255) NOT NULL);
CREATE TABLE users (id INT AUTO_INCREMENT PRIMARY KEY,company_id INT NOT NULL,role ENUM('superadmin','admin','coach','player') NOT NULL,email VARCHAR(255) NOT NULL,password_hash VARCHAR(255) NOT NULL,first_name VARCHAR(100) NOT NULL,last_name VARCHAR(100) NOT NULL,phone VARCHAR(50),created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(company_id) REFERENCES companies(id) ON DELETE CASCADE);
CREATE TABLE reservations (id INT AUTO_INCREMENT PRIMARY KEY,company_id INT NOT NULL,user_id INT NOT NULL,booking_type ENUM('customer','internal') NOT NULL DEFAULT 'customer',customer_first_name VARCHAR(100),customer_last_name VARCHAR(100),customer_email VARCHAR(255),customer_phone VARCHAR(50),created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(company_id) REFERENCES companies(id) ON DELETE CASCADE);
CREATE TABLE email_logs (id INT AUTO_INCREMENT PRIMARY KEY,company_id INT NOT NULL,reservation_id INT,recipient_email VARCHAR(255) NOT NULL,recipient_name VARCHAR(255),type ENUM('admin_notification','customer_summary','confirmation','cancellation','rejection','customer_cancellation','player_activation','password_reset','admin_customer_cancellation') NOT NULL,subject VARCHAR(255) NOT NULL,delivery_status ENUM('sent','failed') NOT NULL,error_message VARCHAR(500),sent_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(company_id) REFERENCES companies(id) ON DELETE CASCADE);
